// 每笔租期先建原应付，再一次 recipe 结清或暂停；所有晚失败依外层完整 Common/LE/Shop/本段保存集撤回。
#include "resident/storage/money_transfer_recipe.hpp"
#include "private_shop_daily_rent_internal.hpp"
#include "resident/domains/local_economy/local_economy_internal.hpp"
#include "resident/domains/organization/organization_office_history.hpp"
namespace hanmo::resident::private_shop_rent_detail {
Outcome<StableId> append(CommonStore& c,const StableId& prefix,const StableId& kind,const StableId& domain){auto id=c.next_id(prefix);if(!id.ok)return id;auto written=c.append_fact({id.value,kind,domain});return written.ok?id:Outcome<StableId>{false,{},written.error};}
Outcome<StableId> pay(CommonStore& c,LocalEconomyState& e,PrivateShopDailyRentState& s,const PrivateShopRecord& shop,const PrivateShopRentAssessment& assessment,const StableId& funding_kind,const StableId& actor,const StableId& payer,const StableId& mandate,const StableId& notice){
 const auto* due=e.arrears.find(assessment.arrear_id);const auto* obligation=e.obligations.find(shop.rent_obligation_id);const auto* from=c.wallet(payer);const auto* through=c.wallet(shop.wallet_id);const auto* to=c.wallet(shop.terms.lessor_wallet_id);if(!due||due->paid_amount||due->original_due!=shop.terms.daily_rent||due->obligation_id!=shop.rent_obligation_id||!obligation||obligation->source_wallet_or_inventory!=shop.wallet_id||obligation->destination!=shop.terms.lessor_wallet_id||!from||!through||!to||from->id==to->id||!owner_equal(through->owner,{Owner::Kind::actor,shop.terms.proprietor_actor_id,{}})||!owner_equal(to->owner,{Owner::Kind::actor,shop.terms.lessor_actor_id,{}}))return {false,{},common_failure("PrivateShopRentPaymentSourceMismatch").error};
 const bool automatic=funding_kind=="automatic_shop",own_shop=funding_kind=="proprietor_shop",own_personal=funding_kind=="proprietor_personal",executor=funding_kind=="executor_personal";const auto* person=c.actor(actor);
 if(automatic?(!actor.empty()||payer!=shop.wallet_id||!mandate.empty()||!notice.empty()):(!person||!owner_equal(from->owner,{Owner::Kind::actor,actor,{}})||(own_shop&&(actor!=shop.terms.proprietor_actor_id||payer!=shop.wallet_id))||(own_personal&&(actor!=shop.terms.proprietor_actor_id||payer!=person->wallet_id))||(executor&&(actor==shop.terms.proprietor_actor_id||payer!=person->wallet_id||mandate.empty()||notice.empty()))||(!own_shop&&!own_personal&&!executor)||(!executor&&(!mandate.empty()||!notice.empty()))))return {false,{},common_failure("PrivateShopRentVoluntaryPayerMismatch").error};
 auto spendable=c.spendable(payer);if(!spendable.ok)return {false,{},spendable.error};if(spendable.value<due->original_due)return {false,{},common_failure("PrivateShopRentFullPaymentRequired").error};const Integer amount=due->original_due,due_tick=due->due_tick;auto id=append(c,private_shop_rent_paid_kind,private_shop_rent_paid_kind,private_shop_daily_rent_module);if(!id.ok)return id;
 ResourceRecipe recipe;if(payer!=shop.wallet_id){auto built=resource_recipe::append_money_transfer(recipe,payer,shop.wallet_id,amount,resource_recipe::MoneyTransferPolicy::spendable_debit_original_credit);if(!built.ok)return {false,{},built.error};}auto changed=resource_recipe::append_money_transfer(recipe,shop.wallet_id,shop.terms.lessor_wallet_id,amount,resource_recipe::MoneyTransferPolicy::spendable_debit_original_credit);if(!changed.ok)return {false,{},changed.error};changed=c.apply_resources(recipe);if(!changed.ok)return {false,{},changed.error};
 auto receipt=append(c,"local_payment","obligation_payment","local_economy");if(!receipt.ok)return receipt;if(!e.payments.insert(receipt.value,{receipt.value,assessment.arrear_id,shop.rent_obligation_id,shop.wallet_id,shop.terms.lessor_wallet_id,c.tick(),due_tick,amount,shop.id}))return {false,{},common_failure("PrivateShopRentDuplicatePayment").error};e.arrears.find(assessment.arrear_id)->paid_amount=amount;e.obligations.find(shop.rent_obligation_id)->last_receipt_id=receipt.value;
 if(!s.payments.insert(id.value,{id.value,assessment.id,receipt.value,funding_kind,actor,payer,mandate,notice,c.tick()}))return {false,{},common_failure("PrivateShopRentDuplicatePaymentSource").error};return id;
}
Outcome<StableId> assess(CommonStore& c,LocalEconomyState& e,PrivateShopState& shops,PrivateShopDailyRentState& s,const StableId& shop_id,Integer period_index,const StableId& trigger,const StableId& resume){
 const auto* found=shops.shops.find(shop_id);if(!found||found->status=="closed")return {false,{},common_failure("PrivateShopRentShopUnavailable").error};const auto shop=*found;auto period=quote_private_shop_rent_period(shop.opened_tick,period_index);if(!period.ok)return {false,{},period.error};if(c.tick()<period.value.from_tick||c.tick()>=period.value.through_tick||(trigger!="opening"&&trigger!="recurring"&&trigger!="resume"))return {false,{},common_failure("PrivateShopRentCalendarMismatch").error};for(const auto& row:s.assessments.rows())if(row.second.shop_id==shop.id){const auto* due=e.arrears.find(row.second.arrear_id);if(row.second.period_index==period_index||!due||due->paid_amount!=due->original_due)return {false,{},common_failure("PrivateShopRentExistingDebt").error};}
 auto cash=c.spendable(shop.wallet_id);if(!cash.ok)return {false,{},cash.error};auto funded=quote_private_shop_rent_funding(shop.terms.daily_rent,cash.value);if(!funded.ok)return {false,{},funded.error};if(trigger!="recurring"&&!funded.value.fully_funded)return {false,{},common_failure("PrivateShopRentFullPaymentRequired").error};auto id=append(c,private_shop_rent_assessed_kind,private_shop_rent_assessed_kind,private_shop_daily_rent_module);if(!id.ok)return id;auto due=append(c,"local_due","contract_payment_due","local_economy");if(!due.ok)return due;PrivateShopRentAssessment a{id.value,shop.id,due.value,trigger,resume,{},c.tick(),period_index};if(!e.arrears.insert(due.value,{due.value,shop.rent_obligation_id,c.tick(),shop.terms.daily_rent,0})||!s.assessments.insert(a.id,a))return {false,{},common_failure("PrivateShopRentDuplicateAssessment").error};if(funded.value.fully_funded){auto paid=pay(c,e,s,shop,a,"automatic_shop",{},shop.wallet_id);if(!paid.ok)return paid;s.assessments.find(a.id)->automatic_payment_fact_id=paid.value;}else shops.shops.find(shop.id)->status="suspended";return id;
}
}
namespace hanmo::resident {
Status initialize_private_shop_rent_in_candidate(CommonStore& c,LocalEconomyState& e,PrivateShopState& shops,PrivateShopDailyRentState& s,const StableId& id){const auto* shop=shops.shops.find(id);const auto serial=organization_instance_sequence(id,private_shop_open_prefix);if(s.version!=1||s.last_step_tick!=c.tick()||!shop||!serial||*serial>INT64_MAX-2||c.state().next_instance_id!=*serial+2||shop->opened_tick!=c.tick()||c.state().facts.order().empty()||c.state().facts.order().back()!=id)return common_failure("PrivateShopRentOpeningBoundaryMismatch");local_economy_detail::CandidateStateGuard<LocalEconomyState> eg(e);local_economy_detail::CandidateStateGuard<PrivateShopState> sg(shops);local_economy_detail::CandidateStateGuard<PrivateShopDailyRentState> rg(s);auto assessed=private_shop_rent_detail::assess(c,e,shops,s,id,0,"opening");if(!assessed.ok)return {false,{},assessed.error};auto valid=validate_private_shop_daily_rent_sources(c,e,shops,PrivateShopDailyRentCatalog{},s);if(!valid.ok)return valid;eg.commit();sg.commit();rg.commit();return common_success();}
Status reconcile_private_shop_daily_rent_in_candidate(CommonStore& c,LocalEconomyState& e,PrivateShopState& shops,PrivateShopDailyRentState& s,const PrivateShopDailyRentCatalog& catalog,const DynamicStepInput& step){auto prior=read_private_shop_rent_before_calendar(c,e,shops,catalog,s,step);if(!prior.ok)return {false,{},prior.error};local_economy_detail::CandidateStateGuard<LocalEconomyState> eg(e);local_economy_detail::CandidateStateGuard<PrivateShopState> sg(shops);local_economy_detail::CandidateStateGuard<PrivateShopDailyRentState> rg(s);for(const auto& old:prior.value){if(old.closed||old.suspended||old.through_tick>c.tick())continue;if(old.through_tick!=c.tick()||old.period_index==INT64_MAX)return common_failure("PrivateShopRentCalendarMismatch",old.shop_id);auto due=private_shop_rent_detail::assess(c,e,shops,s,old.shop_id,old.period_index+1,"recurring");if(!due.ok)return {false,{},due.error};}s.last_step_tick=c.tick();auto valid=validate_private_shop_daily_rent_sources(c,e,shops,catalog,s);if(!valid.ok)return valid;eg.commit();sg.commit();rg.commit();return common_success();}
}
